import{_ as s,o as a,c as p,ai as e}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"开发 Skill 示例库","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/skills.md","filePath":"ai/productivity/dev-spec/skills.md"}'),l={name:"ai/productivity/dev-spec/skills.md"};function i(t,n,r,c,b,d){return a(),p("div",null,[...n[0]||(n[0]=[e(`<h1 id="开发-skill-示例库" tabindex="-1">开发 Skill 示例库 <a class="header-anchor" href="#开发-skill-示例库" aria-label="Permalink to “开发 Skill 示例库”">​</a></h1><blockquote><p>可复用的开发 Skill 分类索引与命令范本。</p></blockquote><h2 id="_01-·-项目管理类" tabindex="-1">01 · 项目管理类 <a class="header-anchor" href="#_01-·-项目管理类" aria-label="Permalink to “01 · 项目管理类”">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>用途</th></tr></thead><tbody><tr><td><code>project-analysis-skill</code></td><td>分析项目现状，产出项目认知报告</td></tr><tr><td><code>project-context-skill</code></td><td>建立和维护项目上下文</td></tr></tbody></table><h2 id="_02-·-开发协作类" tabindex="-1">02 · 开发协作类 <a class="header-anchor" href="#_02-·-开发协作类" aria-label="Permalink to “02 · 开发协作类”">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>用途</th></tr></thead><tbody><tr><td><code>agents-skill</code></td><td>多 Agent 协作开发：评估分工 → 协同执行 → 统一验收</td></tr><tr><td><code>code-review-skill</code></td><td>代码规范审查与问题清单</td></tr><tr><td><code>debugging-skill</code></td><td>报错定位与修复</td></tr></tbody></table><h2 id="_03-·-测试与交付类" tabindex="-1">03 · 测试与交付类 <a class="header-anchor" href="#_03-·-测试与交付类" aria-label="Permalink to “03 · 测试与交付类”">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>用途</th></tr></thead><tbody><tr><td><code>testing-skill</code></td><td>测试用例设计、执行与结果核对</td></tr><tr><td><code>release-skill</code></td><td>交付检查、报告与回滚方案</td></tr></tbody></table><h2 id="_04-·-ai-应用开发类" tabindex="-1">04 · AI 应用开发类 <a class="header-anchor" href="#_04-·-ai-应用开发类" aria-label="Permalink to “04 · AI 应用开发类”">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>用途</th></tr></thead><tbody><tr><td><code>rag-development-skill</code></td><td>RAG 检索增强应用开发</td></tr><tr><td><code>agent-development-skill</code></td><td>Agent 应用开发</td></tr><tr><td><code>mcp-development-skill</code></td><td>MCP 服务开发</td></tr></tbody></table><h2 id="agents-skill-·-多-agent-协作开发" tabindex="-1">agents-skill · 多 Agent 协作开发 <a class="header-anchor" href="#agents-skill-·-多-agent-协作开发" aria-label="Permalink to “agents-skill · 多 Agent 协作开发”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请评估下面的任务是否适合使用多 Agent 协作。如果适合，请自动完成任务拆分、分工、执行和最终验收；如果不适合，请说明原因，并建议使用单 Agent 完成。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任务：</span></span>
<span class="line"><span>&lt;填写具体任务&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 阶段一：任务评估与分工设计</span></span>
<span class="line"><span>1. 分析任务是否可以拆分为相对独立的子任务。</span></span>
<span class="line"><span>2. 检查任务之间的依赖关系、文件冲突和共享接口。</span></span>
<span class="line"><span>3. 判断多 Agent 是否比单 Agent 更高效。</span></span>
<span class="line"><span>4. 如果不适合多 Agent，说明原因并停止多 Agent 编排。</span></span>
<span class="line"><span>5. 如果适合，设计最小化分工方案。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>分工要求：</span></span>
<span class="line"><span>- 明确每个 Agent 的职责和具体任务。</span></span>
<span class="line"><span>- 明确允许修改、只读和禁止修改的文件范围。</span></span>
<span class="line"><span>- 明确共享接口、数据结构和协作约定。</span></span>
<span class="line"><span>- 明确任务依赖和执行顺序。</span></span>
<span class="line"><span>- 指定主 Agent 负责协调、汇总和最终验收。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 阶段二：执行任务</span></span>
<span class="line"><span>1. 按照分工启动各 Agent 执行任务。</span></span>
<span class="line"><span>2. 在任务允许的情况下并行执行，存在依赖时按顺序执行。</span></span>
<span class="line"><span>3. 各 Agent 严格遵守任务边界和项目开发规范。</span></span>
<span class="line"><span>4. 遇到重大设计问题、需求不明确或任务冲突时，暂停相关任务并反馈。</span></span>
<span class="line"><span>5. 主 Agent 持续协调进度，处理协作问题。</span></span>
<span class="line"><span>6. 各 Agent 完成后，汇报修改文件、实现内容、测试结果和遗留问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 阶段三：汇总结果与统一验收</span></span>
<span class="line"><span>主 Agent 收集所有 Agent 的执行结果，并结合实际代码变更和 Git Diff 进行统一检查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检查内容：</span></span>
<span class="line"><span>1. 是否完成原始需求。</span></span>
<span class="line"><span>2. 是否超出任务和文件修改范围。</span></span>
<span class="line"><span>3. 是否存在文件覆盖、修改冲突或重复实现。</span></span>
<span class="line"><span>4. 各模块之间的接口和数据结构是否一致。</span></span>
<span class="line"><span>5. 业务逻辑、异常处理和边界条件是否正确。</span></span>
<span class="line"><span>6. 是否存在代码质量问题。</span></span>
<span class="line"><span>7. 测试是否充分，是否有真实执行证据。</span></span>
<span class="line"><span>8. 是否存在遗留问题或潜在风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>发现问题后：</span></span>
<span class="line"><span>- 明确且影响较小的问题，可以安排对应 Agent 修复。</span></span>
<span class="line"><span>- 涉及多个模块的问题，先协调相关 Agent 确认方案。</span></span>
<span class="line"><span>- 重大设计问题、需求偏差或超出原始范围的问题，先向用户说明。</span></span>
<span class="line"><span>- 修复完成后，重新检查代码并执行必要测试。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 最终交付</span></span>
<span class="line"><span>请输出统一的执行报告：</span></span>
<span class="line"><span>1. 多 Agent 使用评估及分工情况。</span></span>
<span class="line"><span>2. 各 Agent 任务完成情况。</span></span>
<span class="line"><span>3. 实际修改文件及核心实现。</span></span>
<span class="line"><span>4. 发现的问题及修复情况。</span></span>
<span class="line"><span>5. 测试执行情况及结果。</span></span>
<span class="line"><span>6. 未解决的问题和遗留风险。</span></span>
<span class="line"><span>7. 最终验收结论：通过 / 有条件通过 / 未通过。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>注意：</span></span>
<span class="line"><span>- 不得仅凭 Agent 自述判断任务完成。</span></span>
<span class="line"><span>- 不得将未执行的测试标记为通过。</span></span>
<span class="line"><span>- 不得擅自扩大修改范围。</span></span>
<span class="line"><span>- 不得隐瞒未完成事项。</span></span>
<span class="line"><span>- 最终验收由主 Agent 负责。</span></span>
<span class="line"><span>- 如果当前编程工具不支持子 Agent 创建、任务调度或并行执行，必须明确说明这一能力限制，不能假装已经启动了多个 Agent。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br></div></div>`,12)])])}const o=s(l,[["render",i]]);export{u as __pageData,o as default};
